from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/test")
async def test_endpoint(foo: Optional[int] = Form(None)):
    return {"foo": foo}

client = TestClient(app)

def test_empty_string_as_none():
    # Sending foo="" should be interpreted as foo=None
    response = client.post("/test", data={"foo": ""})
    print(f"Status: {response.status_code}")
    print(f"Body: {response.text}")
    assert response.status_code == 200
    assert response.json() == {"foo": None}

